51	   dpe_if.s_axis from_eth_4,
52	   dpe_if.m_axis to_dpe
53	);
54	   import dpe_pkg::*;
55	
56	   typedef enum logic [3:0] {
57	      IDLE,
58	      R0, S0,
59	      R1, S1,
60	      R2, S2,
61	      R3, S3,
62	      R4, S4
63	   } state_t;
64	
65	   state_t state, next_state;
66	
67	   dpe_if to_dpe_sbuff(.clk(from_cpu.clk), .rst(from_cpu.rst));
68	
69	// FSM registers
70	   always_ff @(posedge from_cpu.clk) begin
71	      if (from_cpu.rst) begin
72	         state <= IDLE;
73	      end else begin
74	         state <= next_state;
75	      end
76	   end
77	
78	// FSM transition logic
79	   always_comb begin
80	      next_state = state;
81	
82	      unique case (state)
83	         IDLE: begin
84	            if (!pause) next_state = R0;
85	         end
86	
87	         R0: begin
88	            if (from_cpu.tvalid && to_dpe_sbuff.tready)       next_state = S0;
89	            else if (pause)                                   next_state = IDLE;
90	            else if (!from_cpu.tvalid && to_dpe_sbuff.tready) next_state = R1;
91	         end
92	
93	         S0: begin
94	            if (from_cpu.tlast && from_cpu.tvalid && to_dpe_sbuff.tready) begin
95	               next_state = pause ? IDLE : R1;
96	            end
97	         end
98	
99	         R1: begin
100	            if (from_eth_1.tvalid && to_dpe_sbuff.tready)       next_state = S1;
101	            else if (pause)                                     next_state = IDLE;
102	            else if (!from_eth_1.tvalid && to_dpe_sbuff.tready) next_state = R2;
103	         end
104	
105	         S1: begin
106	            if (from_eth_1.tlast && from_eth_1.tvalid && to_dpe_sbuff.tready) begin
107	               next_state = pause ? IDLE : R2;
108	            end
109	         end
110	
111	         R2: begin
112	            if (from_eth_2.tvalid && to_dpe_sbuff.tready)       next_state = S2;
113	            else if (pause)                                     next_state = IDLE;
114	            else if (!from_eth_2.tvalid && to_dpe_sbuff.tready) next_state = R3;
115	         end
116	
117	         S2: begin
118	            if (from_eth_2.tlast && from_eth_2.tvalid && to_dpe_sbuff.tready) begin
119	               next_state = pause ? IDLE : R3;
120	            end
121	         end
122	
123	         R3: begin
124	            if (from_eth_3.tvalid && to_dpe_sbuff.tready)       next_state = S3;
125	            else if (pause)                                     next_state = IDLE;
126	            else if (!from_eth_3.tvalid && to_dpe_sbuff.tready) next_state = R4;
127	         end
128	
129	         S3: begin
130	            if (from_eth_3.tlast && from_eth_3.tvalid && to_dpe_sbuff.tready) begin
131	               next_state = pause ? IDLE : R4;
132	            end
133	         end
134	
135	         R4: begin
136	            if (from_eth_4.tvalid && to_dpe_sbuff.tready)       next_state = S4;
137	            else if (pause)                                     next_state = IDLE;
138	            else if (!from_eth_4.tvalid && to_dpe_sbuff.tready) next_state = R0;
139	         end
140	
141	         S4: begin
142	            if (from_eth_4.tlast && from_eth_4.tvalid && to_dpe_sbuff.tready) begin
143	               next_state = pause ? IDLE : R0;
144	            end
145	         end
146	
147	         default:
148	            next_state = state;
149	      endcase
150	   end
151	
152	// Outputs logic
153	   always_comb begin
154	      // Default assignments
155	      is_idle = 1'b0;
156	      to_dpe_sbuff.tvalid = 1'b0;
157	      to_dpe_sbuff.tdata = '0;
158	      to_dpe_sbuff.tlast = 1'b0;
159	      to_dpe_sbuff.tkeep = '0;
160	      to_dpe_sbuff.tuser_bypass_all = 1'b0;
161	      to_dpe_sbuff.tuser_bypass_stage = 1'b0;
162	      to_dpe_sbuff.tuser_src = '0;
163	      to_dpe_sbuff.tuser_dst = '0;
164	      from_cpu.tready = 1'b0;
165	      from_eth_1.tready = 1'b0;
166	      from_eth_2.tready = 1'b0;
167	      from_eth_3.tready = 1'b0;
168	      from_eth_4.tready = 1'b0;
169	
170	      unique case (state)
171	         IDLE: begin
172	            is_idle = !to_dpe.tvalid;
173	         end
174	
175	         R0, S0: begin
176	            is_idle = 1'b0;
177	            to_dpe_sbuff.tvalid = from_cpu.tvalid;
178	            to_dpe_sbuff.tdata = from_cpu.tdata;
179	            to_dpe_sbuff.tlast = from_cpu.tlast;
180	            to_dpe_sbuff.tkeep = from_cpu.tkeep;
181	            to_dpe_sbuff.tuser_bypass_all = from_cpu.tuser_bypass_all;
182	            to_dpe_sbuff.tuser_bypass_stage = from_cpu.tuser_bypass_stage;
183	            to_dpe_sbuff.tuser_src = DPE_ADDR_CPU;
184	            to_dpe_sbuff.tuser_dst = from_cpu.tuser_dst;
185	            from_cpu.tready = to_dpe_sbuff.tready;
186	         end
187	
188	         R1, S1: begin
189	            is_idle = 1'b0;
190	            to_dpe_sbuff.tvalid = from_eth_1.tvalid;
191	            to_dpe_sbuff.tdata = from_eth_1.tdata;
192	            to_dpe_sbuff.tlast = from_eth_1.tlast;
193	            to_dpe_sbuff.tkeep = from_eth_1.tkeep;
194	            to_dpe_sbuff.tuser_bypass_all = from_eth_1.tuser_bypass_all;
195	            to_dpe_sbuff.tuser_bypass_stage = from_eth_1.tuser_bypass_stage;
196	            to_dpe_sbuff.tuser_src = DPE_ADDR_ETH_1;
197	            to_dpe_sbuff.tuser_dst = from_eth_1.tuser_dst;
198	            from_eth_1.tready = to_dpe_sbuff.tready;
199	         end
200	
201	         R2, S2: begin
202	            is_idle = 1'b0;
203	            to_dpe_sbuff.tvalid = from_eth_2.tvalid;
204	            to_dpe_sbuff.tdata = from_eth_2.tdata;
205	            to_dpe_sbuff.tlast = from_eth_2.tlast;
206	            to_dpe_sbuff.tkeep = from_eth_2.tkeep;
207	            to_dpe_sbuff.tuser_bypass_all = from_eth_2.tuser_bypass_all;
208	            to_dpe_sbuff.tuser_bypass_stage = from_eth_2.tuser_bypass_stage;
209	            to_dpe_sbuff.tuser_src = DPE_ADDR_ETH_2;
210	            to_dpe_sbuff.tuser_dst = from_eth_2.tuser_dst;
211	            from_eth_2.tready = to_dpe_sbuff.tready;
212	         end
213	
214	         R3, S3: begin
215	            is_idle = 1'b0;
216	            to_dpe_sbuff.tvalid = from_eth_3.tvalid;
217	            to_dpe_sbuff.tdata = from_eth_3.tdata;
218	            to_dpe_sbuff.tlast = from_eth_3.tlast;
219	            to_dpe_sbuff.tkeep = from_eth_3.tkeep;
220	            to_dpe_sbuff.tuser_bypass_all = from_eth_3.tuser_bypass_all;
221	            to_dpe_sbuff.tuser_bypass_stage = from_eth_3.tuser_bypass_stage;
222	            to_dpe_sbuff.tuser_src = DPE_ADDR_ETH_3;
223	            to_dpe_sbuff.tuser_dst = from_eth_3.tuser_dst;
224	            from_eth_3.tready = to_dpe_sbuff.tready;
225	         end
226	
227	         R4, S4: begin
228	            is_idle = 1'b0;
229	            to_dpe_sbuff.tvalid = from_eth_4.tvalid;
230	            to_dpe_sbuff.tdata = from_eth_4.tdata;
231	            to_dpe_sbuff.tlast = from_eth_4.tlast;
232	            to_dpe_sbuff.tkeep = from_eth_4.tkeep;
233	            to_dpe_sbuff.tuser_bypass_all = from_eth_4.tuser_bypass_all;
234	            to_dpe_sbuff.tuser_bypass_stage = from_eth_4.tuser_bypass_stage;
235	            to_dpe_sbuff.tuser_src = DPE_ADDR_ETH_4;
236	            to_dpe_sbuff.tuser_dst = from_eth_4.tuser_dst;
237	            from_eth_4.tready = to_dpe_sbuff.tready;
238	         end
239	
240	         default:
241	            is_idle = !to_dpe.tvalid;
242	      endcase
243	   end
