42	
43	`timescale 1ps/1ps
44	
45	module tb;
46	    // Constants
47	    localparam CLK_PERIOD = 12_500;
48	
49	    // Clock and reset signals
50	    logic clk = 0;
51	    logic rst = 1;
52	    logic pause = 0;
53	
54	    // Interfaces
55	    dpe_if from_cpu(.clk(clk), .rst(rst));
56	    dpe_if from_eth_1(.clk(clk), .rst(rst));
57	    dpe_if from_eth_2(.clk(clk), .rst(rst));
58	    dpe_if from_eth_3(.clk(clk), .rst(rst));
59	    dpe_if from_eth_4(.clk(clk), .rst(rst));
60	    dpe_if to_dpe(.clk(clk), .rst(rst));
61	
62	    // Test data type and constants
63	    typedef logic [7:0] test_data_t [6];
64	    typedef test_data_t packet_data_t [5];
65	
66	    const packet_data_t packet_data = '{
67	        '{8'h01, 8'h02, 8'h03, 8'h04, 8'h05, 8'h06},  // Input 0
68	        '{8'h0B, 8'h0C, 8'h0D, 8'h0E, 8'h00, 8'h00},  // Input 1
69	        '{8'h15, 8'h16, 8'h17, 8'h18, 8'h19, 8'h00},  // Input 2
70	        '{8'h1F, 8'h20, 8'h21, 8'h22, 8'h00, 8'h00},  // Input 3
71	        '{8'h29, 8'h2A, 8'h2B, 8'h2C, 8'h00, 8'h00}   // Input 4
72	    };
73	
74	    // Clock generation
75	    always #(CLK_PERIOD/2) clk <= ~clk;
76	
77	    // DUT instantiation
78	    dpe_multiplexer DUT (
79	        .pause(pause),
80	        .is_idle(),
81	        .from_cpu(from_cpu),
82	        .from_eth_1(from_eth_1),
83	        .from_eth_2(from_eth_2),
84	        .from_eth_3(from_eth_3),
85	        .from_eth_4(from_eth_4),
86	        .to_dpe(to_dpe)
87	    );
88	
89	    // Main stimulus process
90	    initial begin
91	        // Initialize all input interfaces
92	        from_cpu.tvalid = 0;
93	        from_cpu.tlast = 0;
94	        from_cpu.tkeep = '0;
95	        from_cpu.tdata = '0;
96	
97	        from_eth_1.tvalid = 0;
98	        from_eth_1.tlast = 0;
99	        from_eth_1.tkeep = '0;
100	        from_eth_1.tdata = '0;
101	
102	        from_eth_2.tvalid = 0;
103	        from_eth_2.tlast = 0;
104	        from_eth_2.tkeep = '0;
105	        from_eth_2.tdata = '0;
106	
107	        from_eth_3.tvalid = 0;
108	        from_eth_3.tlast = 0;
109	        from_eth_3.tkeep = '0;
110	        from_eth_3.tdata = '0;
111	
112	        from_eth_4.tvalid = 0;
113	        from_eth_4.tlast = 0;
114	        from_eth_4.tkeep = '0;
115	        from_eth_4.tdata = '0;
116	
117	        // Reset assertion
118	        #(CLK_PERIOD * 4);
119	        @(posedge clk);
120	        #1ps;
121	        rst = 0;
122	        #(CLK_PERIOD);
123	
124	        // Start all stimulus processes in parallel
125	        fork
126	            // Input 0 stimulus
127	            begin
128	                @(posedge clk);
129	                #1ps;
130	                from_cpu.tvalid = 1;
131	                for (int i = 0; i < 6; i++) begin
132	                    from_cpu.tdata = '0;
133	                    from_cpu.tdata[7:0] = packet_data[0][i];
134	                    from_cpu.tkeep = '1;
135	                    from_cpu.tlast = (i == 5);
136	                    @(posedge clk);
137	                    while (!from_cpu.tready) @(posedge clk);
138	                    #1ps;
139	                end
140	                from_cpu.tvalid = 0;
141	                from_cpu.tlast = 0;
142	            end
143	
144	            // Input 1 stimulus
145	            begin
146	                @(posedge clk);
147	                #1ps;
148	                from_eth_1.tvalid = 1;
149	                for (int i = 0; i < 4; i++) begin
